// Generates src/generated.ts — one typed React component per custom element.
import { writeFileSync } from 'node:fs';
import { eventSuffix, readComponents } from '../../../scripts/manifest.mjs';

const components = readComponents(new URL('../../elements/custom-elements.json', import.meta.url));

const lines = [
  "'use client';",
  '// Generated by scripts/generate.mjs from @bitkit-ui/elements/custom-elements.json. Do not edit.',
  "import { wrap } from './wrap.js';",
];
const imports = new Map();
for (const c of components) imports.set(c.entry, [...(imports.get(c.entry) ?? []), c.className]);
for (const [entry, classes] of imports) {
  lines.push(`import type { ${classes.join(', ')} } from '@bitkit-ui/elements/${entry}';`);
  lines.push(`import '@bitkit-ui/elements/${entry}';`);
}
lines.push('');
for (const c of components) {
  const events = Object.fromEntries(c.events.map((e) => [`on${eventSuffix(e.name)}`, e.name]));
  const evType = Object.keys(events).length
    ? Object.keys(events)
        .map((k) => `'${k}'`)
        .join(' | ')
    : 'never';
  lines.push(
    `/** ${c.description.split('\n')[0].replace(/\*\//g, '')} */`,
    `export const ${c.name} = wrap<${c.className}, ${evType}>('${c.tag}', ${JSON.stringify(events)} as Record<${evType}, string>, '${c.name}');`,
    '',
  );
}
writeFileSync(new URL('../src/generated.ts', import.meta.url), lines.join('\n'));
console.log(`react: ${components.length} components generated`);
